/* Display-only GLM stage3 book-edge page trail. Other events delegate unchanged. */
(()=>{const role=window.ArenaCharacterModules.glm,previous=role.drawEffect;role.drawEffect=function(c,e,env){if(e.kind!=='swing'||e.characterId!=='glm'||e.stage!==3)return previous?.(c,e,env)??false;const u=Math.max(0,Math.min(1,env.u??1-e.life/e.max)),dir=e.dir||1;c.save();c.translate(e.x+dir*75,e.y-78);c.scale(dir,1);c.globalAlpha=(1-u)*.9;c.beginPath();c.rect(-12,-25,34,50);c.clip();c.lineWidth=1.3;c.strokeStyle='#ebd9af';c.fillStyle='rgba(26,28,36,.35)';for(let j=0;j<3;j++){c.save();c.translate(2+u*10+j*3,-13+j*12);c.rotate(-.2+j*.2+u*.1);c.fillRect(-3,-5,6,10);c.strokeRect(-3,-5,6,10);c.beginPath();c.moveTo(-1,-2);c.lineTo(1,-2);c.moveTo(-1,1);c.lineTo(1,1);c.stroke();c.restore();}c.restore();return true;};})();
